module.exports = [
{ e: "🪶", art: { b: "🪶", s: ["🦬", "🏕️", "🌾", "🦅"], c: ["#1C2E5C", "#3A5AA0"] },
pt: { h: "O vovô pendurou um mapa enorme dos Estados Unidos na parede e colocou um carrinho de brinquedo na beirada. “Vamos fazer uma viagem de mentirinha pela história desse país”, disse. “Cada noite, uma parada e um cartão-postal.” Leo empurrou o carrinho, e o Pipoca tentou pegá-lo com a pata.", t: "As primeiras nações", f: "Muito antes de os europeus chegarem, a América do Norte era a casa de milhões de pessoas, de centenas de povos nativos diferentes. Uns caçavam bisões nas planícies, outros pescavam no mar, outros plantavam milho, feijão e abóbora.", x: "Hoje os Estados Unidos reconhecem mais de 570 nações indígenas, como os Navajo, os Cherokee, os Lakota e os Hopi!", s: ["Muitos povos plantavam milho, feijão e abóbora juntos, um sistema chamado de “as três irmãs”: um planta ajuda a outra a crescer.", "Os nomes de mais da metade dos estados americanos vêm de palavras indígenas, como Dakota, Utah, Texas e Massachusetts.", "As nações indígenas continuam vivas hoje, com suas línguas, governos e tradições."], ex: { t: "As três irmãs no copo", m: "três copinhos com terra, sementes de milho, feijão e abóbora (ou pepino), água", p: ["Plante as sementes num vaso maior, ou uma em cada copinho, bem pertinho.", "Regue um pouco todo dia e deixe num lugar com sol.", "Observe em uma ou duas semanas: o milho cresce reto, o feijão sobe enrolando nele e a abóbora espalha as folhas no chão!"] }, at: "Meu primeiro cartão-postal", m: "um cartão ou papel grosso, lápis de cor", p: ["Desenhe na frente uma paisagem das grandes planícies com bisões.", "Atrás, escreva uma mensagem para alguém contando o que aprendeu hoje.", "Guarde num envelope: esse é o começo da sua coleção de cartões-postais!"], q: "Que planta você gostaria de plantar junto com a sua família?" },
en: { h: "Grandpa hung a huge map of the United States on the wall and set a toy car at the edge. “Let's take a pretend trip through this country's history,” he said. “Every night, one stop and one postcard.” Leo pushed the car, and Popcorn tried to catch it with his paw.", t: "The first nations", f: "Long before Europeans arrived, North America was home to millions of people from hundreds of different Native nations. Some hunted bison on the plains, some fished in the sea and others grew corn, beans and squash.", x: "Today the United States recognizes more than 570 Native nations, such as the Navajo, Cherokee, Lakota and Hopi!", s: ["Many peoples grew corn, beans and squash together, a system called “the three sisters”: each plant helps the others grow.", "The names of more than half the U.S. states come from Native words, like Dakota, Utah, Texas and Massachusetts.", "Native nations are still alive today, with their own languages, governments and traditions."], ex: { t: "Three sisters in a pot", m: "a pot of soil, seeds of corn, beans and squash (or cucumber), water", p: ["Plant the seeds close together in the pot.", "Water them a little every day and keep them somewhere sunny.", "Watch over a week or two: the corn grows straight, the beans climb around it and the squash spreads its leaves on the ground!"] }, at: "My first postcard", m: "a card or thick paper, colored pencils", p: ["On the front, draw a Great Plains landscape with bison.", "On the back, write a message to someone about what you learned today.", "Keep it in an envelope: that's the start of your postcard collection!"], q: "What plant would you like to grow with your family?" },
es: { h: "El abuelo colgó un mapa enorme de Estados Unidos en la pared y puso un autito de juguete en el borde. “Vamos a hacer un viaje de mentira por la historia de este país”, dijo. “Cada noche, una parada y una postal.” Leo empujó el autito, y Palomita intentó atraparlo con la pata.", t: "Las primeras naciones", f: "Mucho antes de que llegaran los europeos, América del Norte era el hogar de millones de personas de cientos de pueblos nativos diferentes. Unos cazaban bisontes en las llanuras, otros pescaban en el mar y otros plantaban maíz, frijoles y calabaza.", x: "¡Hoy Estados Unidos reconoce más de 570 naciones indígenas, como los navajo, los cherokee, los lakota y los hopi!", s: ["Muchos pueblos plantaban maíz, frijoles y calabaza juntos, un sistema llamado “las tres hermanas”: cada planta ayuda a las otras a crecer.", "Los nombres de más de la mitad de los estados vienen de palabras indígenas, como Dakota, Utah, Texas y Massachusetts.", "Las naciones indígenas siguen vivas hoy, con sus lenguas, gobiernos y tradiciones."], ex: { t: "Las tres hermanas en una maceta", m: "una maceta con tierra, semillas de maíz, frijol y calabaza (o pepino), agua", p: ["Planta las semillas bien juntitas en la maceta.", "Riégalas un poco cada día y déjalas en un lugar con sol.", "Observa en una o dos semanas: ¡el maíz crece derecho, el frijol sube enroscándose en él y la calabaza extiende sus hojas por el suelo!"] }, at: "Mi primera postal", m: "una tarjeta o papel grueso, lápices de colores", p: ["En el frente, dibuja un paisaje de las grandes llanuras con bisontes.", "Atrás, escribe un mensaje para alguien contando lo que aprendiste hoy.", "Guárdala en un sobre: ¡es el comienzo de tu colección de postales!"], q: "¿Qué planta te gustaría plantar con tu familia?" } },

{ e: "🏜️", art: { b: "🏜️", s: ["🛖", "⛰️", "🌽", "☀️"], c: ["#5A2A0B", "#C27A3A"] },
pt: { h: "O carrinho parou num deserto vermelho, cheio de paredões de pedra. O vovô mostrou uma foto de casas construídas dentro de um penhasco. “Parece um prédio de apartamentos na rocha!”, disse Nina. “E foi feito há mais de 700 anos”, respondeu o vovô.", t: "Cidades antigas da América do Norte", f: "Os povos antigos da América do Norte construíram lugares incríveis. No sudoeste, os ancestrais dos povos Pueblo fizeram casas de pedra e barro dentro de penhascos. Perto do rio Mississippi, existiu uma grande cidade chamada Cahokia, com montes de terra gigantes.", x: "Por volta do ano 1100, Cahokia era uma das maiores cidades do mundo, com milhares de moradores, maior que Londres na mesma época!", s: ["O maior monte de Cahokia tem uns 30 metros de altura, como um prédio de 10 andares, feito com terra carregada em cestos.", "No Parque Nacional Mesa Verde, no Colorado, o Palácio do Penhasco tem cerca de 150 cômodos.", "As casas no penhasco ficavam protegidas do sol forte no verão e do vento frio no inverno."], ex: { t: "Tijolos de barro", m: "terra argilosa ou massinha de modelar, um pouco de palha seca ou grama, água, forminhas de gelo", p: ["Misture a terra com água até virar uma lama grossa, e acrescente pedacinhos de palha.", "Aperte a mistura nas forminhas de gelo e deixe secar no sol por dois ou três dias.", "Desenforme e monte uma casinha. A palha deixa o tijolo mais forte, como nos adobes antigos!"] }, at: "Cartão-postal do penhasco", m: "cartão, lápis de cor", p: ["Desenhe um penhasco com casinhas quadradas encaixadas dentro dele.", "Coloque escadas de madeira ligando os andares.", "No verso, conte para alguém por que as casas ficavam ali."], q: "Se você fosse construir uma casa num lugar diferente, onde seria?" },
en: { h: "The toy car stopped in a red desert full of rock cliffs. Grandpa showed a photo of houses built right into a cliff. “It looks like an apartment building in the rock!” said Nina. “And it was built more than 700 years ago,” Grandpa replied.", t: "Ancient cities of North America", f: "The ancient peoples of North America built amazing places. In the Southwest, the ancestors of the Pueblo peoples made stone and mud houses inside cliffs. Near the Mississippi River there was a great city called Cahokia, with giant earth mounds.", x: "Around the year 1100, Cahokia was one of the largest cities in the world, with thousands of residents, bigger than London at the time!", s: ["Cahokia's largest mound is about 30 meters (100 feet) tall, as high as a 10-story building, made with soil carried in baskets.", "In Mesa Verde National Park, in Colorado, the Cliff Palace has about 150 rooms.", "The cliff houses were shaded from the hot summer sun and sheltered from cold winter winds."], ex: { t: "Mud bricks", m: "clay-rich soil or modeling clay, a little dry straw or grass, water, ice cube trays", p: ["Mix the soil with water until it becomes thick mud, and add bits of straw.", "Press the mixture into the ice cube trays and let it dry in the sun for two or three days.", "Pop them out and build a little house. The straw makes the bricks stronger, like ancient adobe!"] }, at: "Cliff postcard", m: "a card, colored pencils", p: ["Draw a cliff with little square houses tucked inside.", "Add wooden ladders connecting the levels.", "On the back, tell someone why the houses were built there."], q: "If you built a house somewhere unusual, where would it be?" },
es: { h: "El autito se detuvo en un desierto rojo lleno de paredones de piedra. El abuelo mostró una foto de casas construidas dentro de un acantilado. “¡Parece un edificio de departamentos en la roca!”, dijo Nina. “Y se hizo hace más de 700 años”, respondió el abuelo.", t: "Ciudades antiguas de América del Norte", f: "Los pueblos antiguos de América del Norte construyeron lugares increíbles. En el suroeste, los ancestros de los pueblos pueblo hicieron casas de piedra y barro dentro de acantilados. Cerca del río Misisipi existió una gran ciudad llamada Cahokia, con montículos de tierra gigantes.", x: "¡Alrededor del año 1100, Cahokia era una de las ciudades más grandes del mundo, con miles de habitantes, más grande que Londres en esa época!", s: ["El montículo más grande de Cahokia mide unos 30 metros de alto, como un edificio de 10 pisos, hecho con tierra cargada en cestos.", "En el Parque Nacional Mesa Verde, en Colorado, el Palacio del Acantilado tiene unas 150 habitaciones.", "Las casas del acantilado quedaban protegidas del sol fuerte en verano y del viento frío en invierno."], ex: { t: "Ladrillos de barro", m: "tierra arcillosa o plastilina, un poco de paja seca o pasto, agua, cubeteras de hielo", p: ["Mezcla la tierra con agua hasta formar un barro espeso, y agrega pedacitos de paja.", "Aprieta la mezcla en las cubeteras y déjala secar al sol dos o tres días.", "Desmóldalos y arma una casita. ¡La paja hace que el ladrillo sea más fuerte, como en los adobes antiguos!"] }, at: "Postal del acantilado", m: "una tarjeta, lápices de colores", p: ["Dibuja un acantilado con casitas cuadradas metidas adentro.", "Agrega escaleras de madera que unan los pisos.", "Atrás, cuéntale a alguien por qué las casas estaban allí."], q: "Si construyeras una casa en un lugar diferente, ¿dónde sería?" } },

{ e: "⛵", art: { b: "⛵", s: ["🧭", "🌊", "🏰", "🗺️"], c: ["#0B3A5A", "#2C7AB0"] },
pt: { h: "Leo perguntou quem tinha sido o primeiro europeu a chegar à América. Nina respondeu na hora: “Colombo!”. O vovô sorriu e balançou a cabeça: “Uns 500 anos antes dele, uns navegadores bem barbudos já tinham chegado lá no norte.” Leo ficou curioso: “Quem?”. “Os vikings!”", t: "Os europeus chegam", f: "Por volta do ano 1000, vikings liderados por Leif Erikson chegaram ao norte da América, onde hoje é o Canadá. Quase 500 anos depois, em 1492, Cristóvão Colombo chegou às ilhas do Caribe. Depois vieram espanhóis, franceses, ingleses e holandeses.", x: "A cidade mais antiga fundada por europeus que existe até hoje no território dos Estados Unidos é St. Augustine, na Flórida, criada pelos espanhóis em 1565!", s: ["Os arqueólogos encontraram restos de uma vila viking na Terra Nova, no Canadá.", "Colombo achava que tinha chegado à Índia, e por isso chamou os povos nativos de “índios”.", "A chegada dos europeus trouxe doenças como a varíola, que matou muitos povos nativos que nunca tinham tido contato com elas."], ex: { t: "Bússola de agulha", m: "uma agulha de costura, um ímã, uma rolha fina ou tampinha de plástico, uma tigela com água (com um adulto)", p: ["Com um adulto, esfregue a agulha no ímã umas 30 vezes, sempre no mesmo sentido.", "Coloque a agulha em cima da rolha, boiando na tigela de água.", "Espere: a agulha gira e aponta para o norte! Os navegadores usavam bússolas para cruzar o oceano."] }, at: "Cartão-postal do navio", m: "cartão, lápis de cor", p: ["Desenhe um navio viking com escudos coloridos ou uma caravela com velas grandes.", "Desenhe o mar e uma terra distante no horizonte.", "No verso, escreva como seria passar semanas no mar."], q: "Você teria coragem de cruzar o oceano sem saber o que ia encontrar?" },
en: { h: "Leo asked who was the first European to reach America. Nina answered right away: “Columbus!” Grandpa smiled and shook his head: “About 500 years before him, some very bearded sailors had already reached the north.” Leo was curious: “Who?” “The Vikings!”", t: "Europeans arrive", f: "Around the year 1000, Vikings led by Leif Erikson reached northern America, in what is now Canada. Almost 500 years later, in 1492, Christopher Columbus reached the Caribbean islands. Then came the Spanish, French, English and Dutch.", x: "The oldest city founded by Europeans that still exists in what is now the United States is St. Augustine, Florida, founded by the Spanish in 1565!", s: ["Archaeologists found the remains of a Viking village in Newfoundland, Canada.", "Columbus thought he had reached India, which is why he called the Native peoples “Indians.”", "Europeans brought diseases like smallpox, which killed many Native people who had never been exposed to them."], ex: { t: "Needle compass", m: "a sewing needle, a magnet, a thin cork slice or plastic bottle cap, a bowl of water (with a grown-up)", p: ["With a grown-up, stroke the needle along the magnet about 30 times, always in the same direction.", "Lay the needle on the cork, floating in the bowl of water.", "Wait: the needle turns and points north! Sailors used compasses to cross the ocean."] }, at: "Ship postcard", m: "a card, colored pencils", p: ["Draw a Viking ship with colorful shields or a caravel with big sails.", "Draw the sea and a distant land on the horizon.", "On the back, write what it would be like to spend weeks at sea."], q: "Would you be brave enough to cross the ocean without knowing what you'd find?" },
es: { h: "Leo preguntó quién fue el primer europeo en llegar a América. Nina respondió enseguida: “¡Colón!”. El abuelo sonrió y negó con la cabeza: “Unos 500 años antes que él, unos navegantes muy barbudos ya habían llegado allá al norte.” Leo se puso curioso: “¿Quiénes?”. “¡Los vikingos!”", t: "Llegan los europeos", f: "Alrededor del año 1000, vikingos guiados por Leif Erikson llegaron al norte de América, donde hoy está Canadá. Casi 500 años después, en 1492, Cristóbal Colón llegó a las islas del Caribe. Después vinieron españoles, franceses, ingleses y holandeses.", x: "¡La ciudad más antigua fundada por europeos que sigue existiendo en el territorio de Estados Unidos es San Agustín, en Florida, fundada por los españoles en 1565!", s: ["Los arqueólogos encontraron restos de una aldea vikinga en Terranova, en Canadá.", "Colón creía que había llegado a la India, y por eso llamó “indios” a los pueblos nativos.", "Los europeos trajeron enfermedades como la viruela, que mató a muchos pueblos nativos que nunca habían tenido contacto con ellas."], ex: { t: "Brújula de aguja", m: "una aguja de coser, un imán, una rodaja fina de corcho o tapita de plástico, un tazón con agua (con un adulto)", p: ["Con un adulto, frota la aguja contra el imán unas 30 veces, siempre en el mismo sentido.", "Pon la aguja sobre el corcho, flotando en el tazón con agua.", "Espera: ¡la aguja gira y apunta al norte! Los navegantes usaban brújulas para cruzar el océano."] }, at: "Postal del barco", m: "una tarjeta, lápices de colores", p: ["Dibuja un barco vikingo con escudos de colores o una carabela con velas grandes.", "Dibuja el mar y una tierra lejana en el horizonte.", "Atrás, escribe cómo sería pasar semanas en el mar."], q: "¿Te animarías a cruzar el océano sin saber qué ibas a encontrar?" } },

{ e: "🌽", art: { b: "🌽", s: ["⛵", "🏠", "🦃", "🍂"], c: ["#5A3A0B", "#D48A2C"] },
pt: { h: "Na parada seguinte, o carrinho chegou a uma costa fria e cheia de árvores com folhas laranja. O vovô contou sobre um navio cheio de famílias inglesas que chegou ali no inverno, sem saber plantar naquela terra. “Quem ensinou foram os povos que já moravam lá”, disse.", t: "Os primeiros colonos ingleses", f: "Em 1607, os ingleses fundaram Jamestown, na Virgínia. Em 1620, o navio Mayflower trouxe outro grupo para Plymouth, em Massachusetts. Os Wampanoag, povo nativo da região, ensinaram os recém-chegados a plantar milho e a pescar ali.", x: "Tisquantum, um Wampanoag que ajudou os colonos, já falava inglês porque tinha sido levado à força para a Europa anos antes e conseguido voltar!", s: ["O Mayflower levou 66 dias para atravessar o oceano, com cerca de 100 passageiros.", "Em 1621, colonos e Wampanoag fizeram uma festa de colheita de três dias, que inspirou o feriado de Ação de Graças.", "Pocahontas era uma menina do povo Powhatan quando os ingleses chegaram a Jamestown. Mais tarde, ela viajou para a Inglaterra."], ex: { t: "Peixe que aduba", m: "dois copinhos com terra, sementes de feijão, um pouquinho de casca de banana picada ou borra de café (adubo), água", p: ["Num copinho, misture a terra com a casca de banana picada ou a borra de café. No outro, deixe só a terra.", "Plante feijões nos dois e regue igualzinho.", "Compare em duas semanas: o adubo ajuda a planta! Os Wampanoag ensinaram a colocar peixe na cova do milho como adubo."] }, at: "Cartão-postal da colheita", m: "cartão, lápis de cor", p: ["Desenhe uma mesa de colheita com milho, abóbora e frutas.", "Desenhe pessoas de povos diferentes compartilhando a comida.", "No verso, escreva pelo que você é grato hoje."], q: "Você já ajudou alguém que tinha acabado de chegar num lugar novo?" },
en: { h: "At the next stop, the toy car reached a chilly coast full of trees with orange leaves. Grandpa told them about a ship full of English families that arrived there in winter without knowing how to farm that land. “The people who already lived there taught them,” he said.", t: "The first English colonists", f: "In 1607, the English founded Jamestown, in Virginia. In 1620, the Mayflower brought another group to Plymouth, in Massachusetts. The Wampanoag, the Native people of the region, taught the newcomers how to grow corn and fish there.", x: "Tisquantum, a Wampanoag man who helped the colonists, already spoke English because he had been kidnapped and taken to Europe years earlier and managed to come home!", s: ["The Mayflower took 66 days to cross the ocean, with about 100 passengers.", "In 1621, colonists and Wampanoag shared a three-day harvest feast that inspired the Thanksgiving holiday.", "Pocahontas was a girl of the Powhatan people when the English arrived at Jamestown. Later, she traveled to England."], ex: { t: "Fish fertilizer, kitchen-style", m: "two small cups of soil, bean seeds, a little chopped banana peel or used coffee grounds (fertilizer), water", p: ["In one cup, mix the soil with chopped banana peel or coffee grounds. Leave plain soil in the other.", "Plant beans in both and water them exactly the same.", "Compare after two weeks: fertilizer helps plants grow! The Wampanoag taught colonists to bury a fish in each corn hill as fertilizer."] }, at: "Harvest postcard", m: "a card, colored pencils", p: ["Draw a harvest table with corn, squash and fruit.", "Draw people from different peoples sharing the food.", "On the back, write what you're grateful for today."], q: "Have you ever helped someone who had just arrived somewhere new?" },
es: { h: "En la parada siguiente, el autito llegó a una costa fría llena de árboles con hojas naranjas. El abuelo contó sobre un barco lleno de familias inglesas que llegó allí en invierno, sin saber cultivar esa tierra. “Les enseñaron los pueblos que ya vivían allí”, dijo.", t: "Los primeros colonos ingleses", f: "En 1607, los ingleses fundaron Jamestown, en Virginia. En 1620, el barco Mayflower trajo otro grupo a Plymouth, en Massachusetts. Los wampanoag, pueblo nativo de la región, enseñaron a los recién llegados a plantar maíz y a pescar allí.", x: "¡Tisquantum, un wampanoag que ayudó a los colonos, ya hablaba inglés porque años antes lo habían llevado a la fuerza a Europa y había logrado volver!", s: ["El Mayflower tardó 66 días en cruzar el océano, con unos 100 pasajeros.", "En 1621, colonos y wampanoag compartieron una fiesta de cosecha de tres días que inspiró el feriado de Acción de Gracias.", "Pocahontas era una niña del pueblo powhatan cuando los ingleses llegaron a Jamestown. Más tarde viajó a Inglaterra."], ex: { t: "Abono casero", m: "dos vasitos con tierra, semillas de frijol, un poquito de cáscara de banana picada o borra de café (abono), agua", p: ["En un vasito, mezcla la tierra con la cáscara de banana picada o la borra de café. En el otro deja solo tierra.", "Planta frijoles en los dos y riégalos igualito.", "Compara en dos semanas: ¡el abono ayuda a la planta! Los wampanoag enseñaron a poner un pescado en cada hoyo de maíz como abono."] }, at: "Postal de la cosecha", m: "una tarjeta, lápices de colores", p: ["Dibuja una mesa de cosecha con maíz, calabaza y frutas.", "Dibuja personas de pueblos diferentes compartiendo la comida.", "Atrás, escribe por qué cosa estás agradecido hoy."], q: "¿Alguna vez ayudaste a alguien que acababa de llegar a un lugar nuevo?" } },

{ e: "🏡", art: { b: "🏡", s: ["🕯️", "🪵", "📖", "🐄"], c: ["#3A2A1B", "#8A6A4A"] },
pt: { h: "Leo reclamou que tinha que arrumar o quarto. O vovô riu e contou como era a vida de uma criança nas colônias, há trezentos anos: buscar água no poço, alimentar as galinhas, fazer velas… e aprender as letras numa tabuinha de madeira. Leo arrumou o quarto rapidinho.", t: "A vida nas 13 colônias", f: "Os ingleses criaram 13 colônias na costa leste da América do Norte. As pessoas viviam em fazendas e vilas, faziam quase tudo em casa e dependiam umas das outras. As 13 listras da bandeira americana lembram essas colônias.", x: "As crianças aprendiam a ler com uma “hornbook”, uma tabuinha de madeira com o alfabeto, coberta por uma camada fininha de chifre de boi transparente para proteger o papel!", s: ["Não havia luz elétrica: as famílias usavam velas feitas de sebo ou cera de abelha.", "Muitas crianças estudavam em escolas de uma sala só, com alunos de todas as idades juntos.", "As colônias eram muito diferentes entre si: algumas tinham grandes plantações, outras viviam da pesca e do comércio."], ex: { t: "Manteiga no pote", m: "um pote com tampa bem fechada, creme de leite fresco (nata), uma pitada de sal", p: ["Encha o pote até a metade com o creme de leite e feche bem.", "Chacoalhe sem parar por uns 10 a 15 minutos (revezem!).", "Primeiro vira chantili, depois aparece uma bolota amarela: é manteiga! As crianças coloniais faziam isso todo dia."] }, at: "Minha hornbook", m: "papelão, papel, plástico transparente ou fita larga, lápis", p: ["Recorte o papelão em formato de raquete.", "Escreva o alfabeto e os números de 1 a 10 num papel e cole no papelão.", "Cubra com fita larga transparente, como a camada de chifre, e desenhe um cartão-postal da escola colonial."], q: "Que tarefa de casa você faria se vivesse há trezentos anos?" },
en: { h: "Leo complained about having to clean his room. Grandpa laughed and told him what life was like for a kid in the colonies three hundred years ago: fetching water from the well, feeding the chickens, making candles… and learning letters on a little wooden paddle. Leo cleaned his room in a flash.", t: "Life in the 13 colonies", f: "The English created 13 colonies along the east coast of North America. People lived on farms and in villages, made almost everything at home and depended on one another. The 13 stripes on the U.S. flag stand for those colonies.", x: "Children learned to read with a “hornbook,” a wooden paddle with the alphabet, covered by a very thin layer of see-through cow horn to protect the paper!", s: ["There was no electric light: families used candles made of tallow or beeswax.", "Many children studied in one-room schoolhouses, with students of all ages together.", "The colonies were very different from each other: some had big plantations, others lived by fishing and trade."], ex: { t: "Butter in a jar", m: "a jar with a tight lid, heavy cream, a pinch of salt", p: ["Fill the jar halfway with cream and close it tightly.", "Shake nonstop for about 10 to 15 minutes (take turns!).", "First it becomes whipped cream, then a yellow lump appears: butter! Colonial kids did this every day."] }, at: "My hornbook", m: "cardboard, paper, clear plastic or wide tape, pencil", p: ["Cut the cardboard into a paddle shape.", "Write the alphabet and the numbers 1 to 10 on paper and glue it to the cardboard.", "Cover it with wide clear tape, like the horn layer, and draw a postcard of a colonial school."], q: "What chore would you have if you lived three hundred years ago?" },
es: { h: "Leo se quejó porque tenía que ordenar su cuarto. El abuelo se rió y le contó cómo era la vida de un niño en las colonias hace trescientos años: buscar agua en el pozo, dar de comer a las gallinas, hacer velas… y aprender las letras en una tablita de madera. Leo ordenó su cuarto rapidísimo.", t: "La vida en las 13 colonias", f: "Los ingleses crearon 13 colonias en la costa este de América del Norte. La gente vivía en granjas y aldeas, hacía casi todo en casa y dependía unos de otros. Las 13 franjas de la bandera estadounidense recuerdan esas colonias.", x: "¡Los niños aprendían a leer con un “hornbook”, una tablita de madera con el alfabeto, cubierta por una capa finita de cuerno de buey transparente para proteger el papel!", s: ["No había luz eléctrica: las familias usaban velas de sebo o de cera de abeja.", "Muchos niños estudiaban en escuelas de un solo salón, con alumnos de todas las edades juntos.", "Las colonias eran muy distintas entre sí: algunas tenían grandes plantaciones, otras vivían de la pesca y el comercio."], ex: { t: "Manteca en un frasco", m: "un frasco con tapa bien cerrada, crema de leche, una pizca de sal", p: ["Llena el frasco hasta la mitad con la crema y ciérralo bien.", "Agítalo sin parar unos 10 a 15 minutos (¡túrnense!).", "Primero se hace crema batida, después aparece una bola amarilla: ¡es manteca! Los niños coloniales hacían esto todos los días."] }, at: "Mi hornbook", m: "cartón, papel, plástico transparente o cinta ancha, lápiz", p: ["Recorta el cartón con forma de paleta.", "Escribe el alfabeto y los números del 1 al 10 en un papel y pégalo en el cartón.", "Cúbrelo con cinta ancha transparente, como la capa de cuerno, y dibuja una postal de la escuela colonial."], q: "¿Qué tarea de la casa harías si vivieras hace trescientos años?" } },

{ e: "🌍", art: { b: "🕊️", s: ["🌊", "⛵", "💔", "🌍"], c: ["#2A1B0B", "#7A4A1B"] },
pt: { h: "O vovô parou o carrinho no mapa e ficou um tempo calado. “Assim como no Brasil, aqui também aconteceu uma grande injustiça”, disse. Nina lembrou do Álbum do Brasil e falou baixinho: “A escravidão.” O vovô concordou e explicou que é importante conhecer essa história para entender o país de hoje.", t: "A escravidão nos Estados Unidos", f: "A partir de 1619, pessoas africanas foram trazidas à força para as colônias inglesas e escravizadas. Elas eram obrigadas a trabalhar nas plantações de tabaco, arroz e algodão, sem pagamento e sem liberdade.", x: "Em 1860, cerca de 4 milhões de pessoas viviam escravizadas nos Estados Unidos, a maioria nos estados do sul.", s: ["Era proibido por lei ensinar pessoas escravizadas a ler em vários estados do sul, mas muitas aprenderam escondido.", "Mesmo com tanta dor, as comunidades afro-americanas criaram canções, histórias e tradições que influenciaram toda a cultura do país.", "Os spirituals, canções cantadas pelos escravizados, deram origem a estilos como o gospel e influenciaram o blues e o jazz."], ex: { t: "A palavra escondida", m: "papel branco, um giz de cera branco, tinta aquarela ou canetinha clara diluída em água, pincel", p: ["Escreva com o giz de cera branco uma palavra importante, como “liberdade”, no papel branco.", "Ela quase não aparece, não é?", "Pinte por cima com a aquarela: a palavra aparece, porque a cera não deixa a tinta grudar. Assim como as pessoas que aprendiam a ler escondido, ela estava lá o tempo todo."] }, at: "Canção de esperança", m: "papel, lápis", p: ["Converse com um adulto sobre o que é esperança.", "Escreva uma frase curta de esperança, como um refrão de música.", "Cante ou leia em voz alta com a família e desenhe um cartão-postal com um sol nascendo."], q: "Por que você acha que a música ajudava as pessoas a ter força?" },
en: { h: "Grandpa stopped the car on the map and was quiet for a moment. “Just like in Brazil, a great injustice happened here too,” he said. Nina remembered the Brazil Album and said softly, “Slavery.” Grandpa nodded and explained that it's important to know this history to understand the country today.", t: "Slavery in the United States", f: "Starting in 1619, African people were brought by force to the English colonies and enslaved. They were made to work on tobacco, rice and cotton plantations, without pay and without freedom.", x: "By 1860, about 4 million people were living in slavery in the United States, most of them in the southern states.", s: ["In several southern states it was against the law to teach enslaved people to read, but many learned in secret.", "Even with so much pain, African American communities created songs, stories and traditions that shaped the whole country's culture.", "Spirituals, songs sung by enslaved people, gave rise to gospel and influenced blues and jazz."], ex: { t: "The hidden word", m: "white paper, a white crayon, watercolors or a light marker diluted in water, a brush", p: ["With the white crayon, write an important word, like “freedom,” on the white paper.", "You can barely see it, right?", "Paint over it with watercolor: the word appears, because the wax keeps the paint from sticking. Just like the people who learned to read in secret, it was there all along."] }, at: "Song of hope", m: "paper, pencil", p: ["Talk with a grown-up about what hope means.", "Write a short line of hope, like a song chorus.", "Sing it or read it aloud with your family and draw a postcard of a sunrise."], q: "Why do you think music helped people stay strong?" },
es: { h: "El abuelo detuvo el autito en el mapa y se quedó un rato callado. “Igual que en Brasil, aquí también hubo una gran injusticia”, dijo. Nina se acordó del Álbum de Brasil y dijo bajito: “La esclavitud.” El abuelo asintió y explicó que es importante conocer esta historia para entender el país de hoy.", t: "La esclavitud en Estados Unidos", f: "A partir de 1619, personas africanas fueron traídas a la fuerza a las colonias inglesas y esclavizadas. Las obligaban a trabajar en las plantaciones de tabaco, arroz y algodón, sin paga y sin libertad.", x: "En 1860, cerca de 4 millones de personas vivían esclavizadas en Estados Unidos, la mayoría en los estados del sur.", s: ["En varios estados del sur estaba prohibido por ley enseñar a leer a las personas esclavizadas, pero muchas aprendieron a escondidas.", "Aun con tanto dolor, las comunidades afroamericanas crearon canciones, historias y tradiciones que influyeron en toda la cultura del país.", "Los spirituals, canciones cantadas por las personas esclavizadas, dieron origen al gospel e influyeron en el blues y el jazz."], ex: { t: "La palabra escondida", m: "papel blanco, una crayola blanca, acuarela o un marcador claro diluido en agua, pincel", p: ["Con la crayola blanca, escribe una palabra importante, como “libertad”, en el papel blanco.", "Casi no se ve, ¿verdad?", "Pinta encima con la acuarela: la palabra aparece, porque la cera no deja que la pintura se pegue. Igual que las personas que aprendían a leer a escondidas, estuvo ahí todo el tiempo."] }, at: "Canción de esperanza", m: "papel, lápiz", p: ["Conversa con un adulto sobre qué es la esperanza.", "Escribe una frase corta de esperanza, como el estribillo de una canción.", "Cántala o léela en voz alta con tu familia y dibuja una postal con un sol saliendo."], q: "¿Por qué crees que la música ayudaba a las personas a tener fuerza?" } },

{ e: "🪁", art: { b: "🪁", s: ["⚡", "👓", "📚", "🔑"], c: ["#2A2350", "#5A4AA0"] },
pt: { h: "Num dia de muito vento, Nina e Leo foram soltar pipa. Quando o céu escureceu, o vovô chamou os dois para dentro na hora. “Pipa e tempestade não combinam”, disse sério. Depois contou de um homem que fez exatamente isso, há quase 300 anos, e teve muita sorte de não se machucar.", t: "Benjamin Franklin, o curioso", f: "Benjamin Franklin foi escritor, cientista, inventor e um dos fundadores dos Estados Unidos. Em 1752, ele fez um experimento famoso com uma pipa numa tempestade para mostrar que o raio é eletricidade. Isso foi muito perigoso: nunca tente!", x: "Quando era criança, Franklin inventou nadadeiras de madeira para as mãos, para nadar mais rápido!", s: ["Ele inventou o para-raios, que protege prédios até hoje, e os óculos bifocais, que têm dois tipos de lente.", "Franklin ajudou a criar uma das primeiras bibliotecas públicas de empréstimo da América.", "Ele também foi um dos homens que assinaram a Declaração de Independência."], ex: { t: "Eletricidade no balão", m: "uma bexiga cheia, papel picadinho, cabelo seco", p: ["Esfregue a bexiga no cabelo por uns 10 segundos.", "Aproxime a bexiga do papel picadinho, sem encostar.", "Os papeizinhos pulam e grudam! É eletricidade estática, a mesma “família” de eletricidade do raio, só que bem fraquinha e segura."] }, at: "Almanaque do inventor", m: "papel, lápis de cor", p: ["Franklin escrevia um almanaque com conselhos e frases curtas. Escreva três conselhos seus.", "Invente uma coisa que facilitaria o seu dia e desenhe como ela funciona.", "Faça um cartão-postal com o desenho da sua invenção."], q: "Se você pudesse inventar algo para ajudar a sua família, o que seria?" },
en: { h: "On a very windy day, Nina and Leo went to fly a kite. When the sky turned dark, Grandpa called them inside right away. “Kites and storms don't mix,” he said seriously. Then he told them about a man who did exactly that almost 300 years ago and was very lucky not to get hurt.", t: "Benjamin Franklin, the curious one", f: "Benjamin Franklin was a writer, scientist, inventor and one of the founders of the United States. In 1752, he did a famous experiment with a kite in a storm to show that lightning is electricity. It was very dangerous: never try it!", x: "As a boy, Franklin invented wooden fins for his hands so he could swim faster!", s: ["He invented the lightning rod, which still protects buildings today, and bifocal glasses, which have two kinds of lenses.", "Franklin helped create one of the first public lending libraries in America.", "He was also one of the men who signed the Declaration of Independence."], ex: { t: "Balloon electricity", m: "an inflated balloon, tiny bits of paper, dry hair", p: ["Rub the balloon on your hair for about 10 seconds.", "Bring the balloon close to the bits of paper without touching them.", "The bits jump up and stick! That's static electricity, the same “family” as lightning, only very weak and safe."] }, at: "Inventor's almanac", m: "paper, colored pencils", p: ["Franklin wrote an almanac full of advice and short sayings. Write three sayings of your own.", "Invent something that would make your day easier and draw how it works.", "Make a postcard with a drawing of your invention."], q: "If you could invent something to help your family, what would it be?" },
es: { h: "Un día de mucho viento, Nina y Leo fueron a remontar un barrilete. Cuando el cielo se oscureció, el abuelo los llamó adentro enseguida. “Barriletes y tormentas no combinan”, dijo serio. Después les contó de un hombre que hizo justamente eso hace casi 300 años y tuvo mucha suerte de no lastimarse.", t: "Benjamin Franklin, el curioso", f: "Benjamin Franklin fue escritor, científico, inventor y uno de los fundadores de Estados Unidos. En 1752 hizo un experimento famoso con una cometa en una tormenta para mostrar que el rayo es electricidad. Fue muy peligroso: ¡nunca lo intentes!", x: "¡De niño, Franklin inventó unas aletas de madera para las manos, para nadar más rápido!", s: ["Inventó el pararrayos, que protege edificios hasta hoy, y los anteojos bifocales, que tienen dos tipos de lente.", "Franklin ayudó a crear una de las primeras bibliotecas públicas de préstamo de América.", "También fue uno de los hombres que firmaron la Declaración de Independencia."], ex: { t: "Electricidad en el globo", m: "un globo inflado, papelitos picados, pelo seco", p: ["Frota el globo en tu pelo unos 10 segundos.", "Acerca el globo a los papelitos sin tocarlos.", "¡Los papelitos saltan y se pegan! Es electricidad estática, de la misma “familia” que el rayo, pero muy débil y segura."] }, at: "Almanaque del inventor", m: "papel, lápices de colores", p: ["Franklin escribía un almanaque con consejos y frases cortas. Escribe tres consejos tuyos.", "Inventa algo que haría tu día más fácil y dibuja cómo funciona.", "Haz una postal con el dibujo de tu invento."], q: "Si pudieras inventar algo para ayudar a tu familia, ¿qué sería?" } },

{ e: "🫖", art: { b: "🫖", s: ["⚓", "📦", "🌊", "🔔"], c: ["#0B3A3A", "#2C8A7A"] },
pt: { h: "O vovô serviu chá para os três, e Leo perguntou se podia jogar o chá dele pela janela. “Hoje até que combina com a história”, riu o vovô, mas não deixou. “Uma vez, um grupo de pessoas jogou toneladas de chá no mar, de propósito, para protestar.”", t: "A Festa do Chá de Boston", f: "A Inglaterra cobrava impostos dos colonos sem que eles pudessem votar no Parlamento inglês. Os colonos diziam: “Nada de impostos sem representação!”. Em 1773, em Boston, um grupo jogou no mar o chá de três navios, em protesto.", x: "Foram jogados no mar 342 caixotes de chá, o suficiente para fazer milhões de xícaras!", s: ["O protesto aconteceu à noite, no dia 16 de dezembro de 1773.", "A Inglaterra respondeu fechando o porto de Boston, e a tensão só aumentou.", "Até hoje existe um museu em Boston com réplicas dos navios do protesto."], ex: { t: "Chá que se espalha", m: "dois copos transparentes, água gelada e água morna da torneira, dois saquinhos de chá", p: ["Coloque água gelada num copo e morna no outro (com ajuda de um adulto).", "Mergulhe um saquinho de chá em cada um, ao mesmo tempo, sem mexer.", "Observe a cor saindo: na água morna, o chá se espalha muito mais rápido!"] }, at: "Cartaz de protesto pacífico", m: "cartolina, lápis de cor", p: ["Pense em algo que você acha injusto na escola ou na cidade, como lixo no parque.", "Faça um cartaz com uma frase curta e educada pedindo a mudança.", "Desenhe um cartão-postal do porto de Boston com os caixotes boiando."], q: "Qual é um jeito pacífico de mostrar que você não concorda com algo?" },
en: { h: "Grandpa poured tea for the three of them, and Leo asked if he could throw his tea out the window. “Today it would fit the story,” Grandpa laughed, but he didn't let him. “Once, a group of people threw tons of tea into the sea on purpose, as a protest.”", t: "The Boston Tea Party", f: "England taxed the colonists even though they couldn't vote in the English Parliament. The colonists said, “No taxation without representation!” In 1773, in Boston, a group dumped the tea from three ships into the harbor as a protest.", x: "They dumped 342 chests of tea into the sea, enough to make millions of cups!", s: ["The protest happened at night, on December 16, 1773.", "England responded by closing the port of Boston, and tensions only grew.", "Today there's a museum in Boston with replicas of the protest ships."], ex: { t: "Spreading tea", m: "two clear glasses, ice water and warm tap water, two tea bags", p: ["Put ice water in one glass and warm water in the other (with a grown-up's help).", "Dip a tea bag into each one at the same time, without stirring.", "Watch the color come out: in warm water, the tea spreads much faster!"] }, at: "Peaceful protest poster", m: "poster board, colored pencils", p: ["Think of something you find unfair at school or in town, like litter in the park.", "Make a poster with a short, polite message asking for change.", "Draw a postcard of Boston Harbor with the chests floating."], q: "What's a peaceful way to show you disagree with something?" },
es: { h: "El abuelo sirvió té para los tres, y Leo preguntó si podía tirar su té por la ventana. “Hoy combinaría con la historia”, se rió el abuelo, pero no lo dejó. “Una vez, un grupo de personas tiró toneladas de té al mar, a propósito, como protesta.”", t: "El Motín del Té de Boston", f: "Inglaterra cobraba impuestos a los colonos aunque ellos no podían votar en el Parlamento inglés. Los colonos decían: “¡Nada de impuestos sin representación!”. En 1773, en Boston, un grupo tiró al mar el té de tres barcos como protesta.", x: "¡Tiraron al mar 342 cajones de té, suficiente para preparar millones de tazas!", s: ["La protesta ocurrió de noche, el 16 de diciembre de 1773.", "Inglaterra respondió cerrando el puerto de Boston, y la tensión siguió creciendo.", "Hoy existe un museo en Boston con réplicas de los barcos de la protesta."], ex: { t: "Té que se esparce", m: "dos vasos transparentes, agua helada y agua tibia de la canilla, dos saquitos de té", p: ["Pon agua helada en un vaso y tibia en el otro (con ayuda de un adulto).", "Mete un saquito de té en cada uno al mismo tiempo, sin revolver.", "Mira cómo sale el color: ¡en el agua tibia el té se esparce mucho más rápido!"] }, at: "Cartel de protesta pacífica", m: "cartulina, lápices de colores", p: ["Piensa en algo que te parezca injusto en la escuela o en la ciudad, como basura en la plaza.", "Haz un cartel con una frase corta y educada pidiendo el cambio.", "Dibuja una postal del puerto de Boston con los cajones flotando."], q: "¿Cuál es una forma pacífica de mostrar que no estás de acuerdo con algo?" } },

{ e: "📜", art: { b: "📜", s: ["🖋️", "🔔", "🎆", "🦅"], c: ["#5A0B1B", "#B02C3A"] },
pt: { h: "Leo viu na TV uma festa com fogos de artifício e bandeiras. “É aniversário de alguém?”, perguntou. “Do país!”, disse o vovô. “Todo 4 de julho, os Estados Unidos comemoram o dia em que se declararam independentes.” Nina quis saber o que estava escrito no papel tão famoso.", t: "A Declaração de Independência", f: "Em 4 de julho de 1776, representantes das 13 colônias aprovaram a Declaração de Independência, escrita principalmente por Thomas Jefferson. Ela dizia que as colônias não pertenciam mais à Inglaterra e que todas as pessoas têm direito à vida, à liberdade e à busca da felicidade.", x: "A Declaração dizia que “todos os homens são criados iguais”, mas na época isso não valia para as pessoas escravizadas, para as mulheres e para os povos nativos. Muita gente lutou depois para que essa frase valesse para todos!", s: ["Ela foi assinada por 56 representantes.", "O documento original fica nos Arquivos Nacionais, em Washington, protegido por um vidro especial.", "Depois da declaração, houve uma guerra contra a Inglaterra, que durou até 1783."], ex: { t: "Papel envelhecido", m: "uma folha de papel, um saquinho de chá ou um pouco de café frio, uma bandeja, um adulto", p: ["Amasse a folha e desamasse, para ela ficar cheia de marquinhas.", "Coloque na bandeja e passe o chá ou o café frio com a mão ou um pincel.", "Deixe secar: o papel fica com cara de documento antigo! Use para a atividade de hoje."] }, at: "Minha declaração", m: "o papel envelhecido, caneta", p: ["Escreva uma “declaração” com três direitos que toda criança deveria ter.", "Peça para a família assinar embaixo, como os representantes de 1776.", "Desenhe fogos de artifício num cartão-postal de 4 de julho."], q: "O que significa, para você, que todas as pessoas são iguais?" },
en: { h: "Leo saw a party on TV with fireworks and flags. “Is it someone's birthday?” he asked. “The country's!” said Grandpa. “Every July 4th, the United States celebrates the day it declared independence.” Nina wanted to know what was written on that famous paper.", t: "The Declaration of Independence", f: "On July 4, 1776, representatives of the 13 colonies approved the Declaration of Independence, written mainly by Thomas Jefferson. It said the colonies no longer belonged to England and that all people have the right to life, liberty and the pursuit of happiness.", x: "The Declaration said that “all men are created equal,” but at the time that didn't include enslaved people, women or Native peoples. Many people fought afterward to make those words true for everyone!", s: ["It was signed by 56 representatives.", "The original document is kept at the National Archives in Washington, protected by special glass.", "After the declaration, there was a war against England that lasted until 1783."], ex: { t: "Old-looking paper", m: "a sheet of paper, a tea bag or some cold coffee, a tray, a grown-up", p: ["Crumple the sheet and flatten it out so it's full of creases.", "Put it on the tray and dab the tea or cold coffee on it with your hand or a brush.", "Let it dry: the paper looks like an old document! Use it for today's activity."] }, at: "My declaration", m: "the old-looking paper, a pen", p: ["Write a “declaration” with three rights every child should have.", "Ask your family to sign at the bottom, like the representatives in 1776.", "Draw fireworks on a Fourth of July postcard."], q: "What does it mean to you that all people are equal?" },
es: { h: "Leo vio en la tele una fiesta con fuegos artificiales y banderas. “¿Es el cumpleaños de alguien?”, preguntó. “¡Del país!”, dijo el abuelo. “Cada 4 de julio, Estados Unidos celebra el día en que se declaró independiente.” Nina quiso saber qué decía ese papel tan famoso.", t: "La Declaración de Independencia", f: "El 4 de julio de 1776, representantes de las 13 colonias aprobaron la Declaración de Independencia, escrita sobre todo por Thomas Jefferson. Decía que las colonias ya no pertenecían a Inglaterra y que todas las personas tienen derecho a la vida, la libertad y la búsqueda de la felicidad.", x: "¡La Declaración decía que “todos los hombres son creados iguales”, pero en esa época eso no valía para las personas esclavizadas, las mujeres ni los pueblos nativos. Mucha gente luchó después para que esa frase valiera para todos!", s: ["La firmaron 56 representantes.", "El documento original está en los Archivos Nacionales, en Washington, protegido por un vidrio especial.", "Después de la declaración hubo una guerra contra Inglaterra que duró hasta 1783."], ex: { t: "Papel envejecido", m: "una hoja de papel, un saquito de té o un poco de café frío, una bandeja, un adulto", p: ["Arruga la hoja y estírala, para que quede llena de marquitas.", "Ponla en la bandeja y pásale el té o el café frío con la mano o un pincel.", "Déjala secar: ¡el papel parece un documento antiguo! Úsalo para la actividad de hoy."] }, at: "Mi declaración", m: "el papel envejecido, bolígrafo", p: ["Escribe una “declaración” con tres derechos que todo niño debería tener.", "Pide a tu familia que firme abajo, como los representantes de 1776.", "Dibuja fuegos artificiales en una postal del 4 de julio."], q: "¿Qué significa para ti que todas las personas son iguales?" } },

{ e: "🎖️", art: { b: "🏛️", s: ["🦷", "🎩", "🐎", "⭐"], c: ["#1C2E5C", "#5A6AB0"] },
pt: { h: "Nina perdeu um dente de leite e guardou numa caixinha. O vovô aproveitou para contar uma curiosidade: “O primeiro presidente dos Estados Unidos quase não tinha dentes e usava dentaduras.” Leo fez uma careta: “De madeira?”. “Não! Essa é uma lenda famosa”, riu o vovô.", t: "George Washington, o primeiro presidente", f: "George Washington comandou o exército das colônias na guerra pela independência. Depois da vitória, em 1789, ele se tornou o primeiro presidente dos Estados Unidos. A capital do país, Washington, ganhou o nome dele.", x: "Washington nunca morou na Casa Branca! Ela só ficou pronta em 1800, e o primeiro presidente a morar lá foi John Adams.", s: ["As dentaduras de Washington não eram de madeira: eram feitas de marfim, metal e dentes de animais e de pessoas.", "Ele poderia ter continuado no poder, mas decidiu sair depois de dois mandatos, um exemplo seguido por muitos presidentes.", "O rosto dele aparece na nota de 1 dólar."], ex: { t: "Ovo na água com dentes", m: "dois copos, vinagre, água, dois ovos cozidos com casca (ou casquinhas de ovo)", p: ["Coloque um ovo num copo com água e outro num copo com vinagre.", "Espere um dia e compare as cascas.", "A casca no vinagre fica fininha! A casca do ovo é parecida com o esmalte dos dentes, e os ácidos de doces e refrigerantes fazem algo parecido. Por isso escovamos os dentes!"] }, at: "Retrato de presidente", m: "papel, lápis de cor", p: ["Imagine que você foi eleito líder da sua sala.", "Desenhe seu retrato oficial, bem elegante.", "Escreva três promessas que você cumpriria e faça um cartão-postal da capital, Washington."], q: "Que qualidades um bom líder precisa ter?" },
en: { h: "Nina lost a baby tooth and kept it in a little box. Grandpa used the moment to share a fun fact: “The first president of the United States had hardly any teeth and wore dentures.” Leo made a face: “Wooden ones?” “No! That's a famous myth,” Grandpa laughed.", t: "George Washington, the first president", f: "George Washington led the colonies' army in the war for independence. After the victory, in 1789, he became the first president of the United States. The nation's capital, Washington, D.C., was named after him.", x: "Washington never lived in the White House! It wasn't finished until 1800, and the first president to live there was John Adams.", s: ["Washington's dentures weren't wooden: they were made of ivory, metal and animal and human teeth.", "He could have stayed in power, but he chose to step down after two terms, an example many presidents followed.", "His face appears on the 1-dollar bill."], ex: { t: "Tooth-like eggshells", m: "two glasses, vinegar, water, two hard-boiled eggs in their shells (or eggshell pieces)", p: ["Put one egg in a glass of water and the other in a glass of vinegar.", "Wait a day and compare the shells.", "The shell in vinegar gets very thin! Eggshell is a bit like tooth enamel, and acids in sweets and sodas do something similar. That's why we brush our teeth!"] }, at: "Presidential portrait", m: "paper, colored pencils", p: ["Imagine you've been elected class leader.", "Draw your official portrait, very fancy.", "Write three promises you'd keep and make a postcard of the capital, Washington, D.C."], q: "What qualities does a good leader need?" },
es: { h: "A Nina se le cayó un diente de leche y lo guardó en una cajita. El abuelo aprovechó para contar una curiosidad: “El primer presidente de Estados Unidos casi no tenía dientes y usaba dentaduras postizas.” Leo hizo una mueca: “¿De madera?”. “¡No! Esa es una leyenda famosa”, se rió el abuelo.", t: "George Washington, el primer presidente", f: "George Washington dirigió el ejército de las colonias en la guerra por la independencia. Después de la victoria, en 1789, se convirtió en el primer presidente de Estados Unidos. La capital del país, Washington, lleva su nombre.", x: "¡Washington nunca vivió en la Casa Blanca! Recién estuvo lista en 1800, y el primer presidente que vivió allí fue John Adams.", s: ["Las dentaduras de Washington no eran de madera: estaban hechas de marfil, metal y dientes de animales y de personas.", "Podría haber seguido en el poder, pero decidió irse después de dos mandatos, un ejemplo que siguieron muchos presidentes.", "Su cara aparece en el billete de 1 dólar."], ex: { t: "Cáscaras como dientes", m: "dos vasos, vinagre, agua, dos huevos duros con cáscara (o pedacitos de cáscara)", p: ["Pon un huevo en un vaso con agua y el otro en un vaso con vinagre.", "Espera un día y compara las cáscaras.", "¡La cáscara en el vinagre queda finita! La cáscara del huevo se parece al esmalte de los dientes, y los ácidos de las golosinas y gaseosas hacen algo parecido. ¡Por eso nos cepillamos los dientes!"] }, at: "Retrato presidencial", m: "papel, lápices de colores", p: ["Imagina que te eligieron líder de tu clase.", "Dibuja tu retrato oficial, bien elegante.", "Escribe tres promesas que cumplirías y haz una postal de la capital, Washington."], q: "¿Qué cualidades necesita un buen líder?" } },
];
